      handleFailure(envoy::data::core::v3::ACTIVE);  
  }  
  Processes the result of the health check and invokes either success or failure callbacks.

- const bool goaway = received_no_error_goaway_;  
  Reads this flag (which indicates whether a NO_ERROR GOAWAY frame was received).

- if (end_stream) {  
      resetState();  
  } else {  
      expect_reset_ = true;  
      request_encoder_->getStream().resetStream(Http::StreamResetReason::LocalReset);  
  }  
